export async function apiRequest(url, options = {}) {
    const defaultOptions = {
        headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
        },
    }
    
    const merged = {
        ...defaultOptions,
        ...options,
        headers: {
            ...defaultOptions.headers,
            ...options.headers,
        },
    }
    
    try {
        const response = await fetch(url, merged)
        
        if (!response.ok) {
            const errorText = await response.text()
            throw new Error(`HTTP ${response.status}: ${errorText}`)
        }
        
        return await response.json()
    } catch (error) {
        console.error('[apiRequest] Failed:', url, error)
        throw error
    }
}

export function debounce(fn, delay) {
    let timer
    const debounced = (...args) => {
        clearTimeout(timer)
        timer = setTimeout(() => fn(...args), delay)
    }
    debounced.cancel = () => clearTimeout(timer)
    return debounced
}

export function saveToSession(key, data) {
    try {
        sessionStorage.setItem(key, JSON.stringify(data))
    } catch (e) {
        console.error('Session save failed:', e)
    }
}

export function loadFromSession(key, ttl = null) {
    try {
        const raw = sessionStorage.getItem(key)
        if (!raw) return null
        
        const data = JSON.parse(raw)
        
        if (ttl && data._timestamp && Date.now() - data._timestamp > ttl) {
            sessionStorage.removeItem(key)
            return null
        }
        
        return data
    } catch (e) {
        console.error('Session load failed:', e)
        return null
    }
}

export function clearSession(key) {
    sessionStorage.removeItem(key)
}

export function formatTime(seconds) {
    if (seconds <= 0) return '00:00'
    const mins = Math.floor(seconds / 60)
    const secs = seconds % 60
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`
}

export function announce(message, priority = 'polite') {
    const elId = priority === 'assertive' ? 'aria-live-assertive' : 'aria-live-polite'
    const el = document.getElementById(elId)
    if (el) {
        el.textContent = message
        setTimeout(() => { el.textContent = '' }, 1000)
    }
}