import React, { useState, useCallback, useEffect, useRef, memo } from 'react'
import { formatTime, announce } from '../shared/api'

const FILTER_TYPES = ['all', 'correct', 'wrong', 'skipped']
const statusLabels = { correct: 'Correct', wrong: 'Wrong', skipped: 'Skipped' }

// BUG FIX #27: Memo receives stable primitive props, not new objects
const ReviewItem = memo(function ReviewItem({ index, questionText, userText, correctText, explanation, status }) {
  return (
    <div className={`review-item ${status}`} data-status={status}>
      <div className="review-head">
        <span>Q{index + 1}</span>
        <span className={`review-badge ${status}`}>
          {statusLabels[status] || status}
        </span>
      </div>
      <div className="review-body">
        <p>{questionText}</p>
        <p>
          <strong>Your:</strong> {userText} | <strong>Correct:</strong> {correctText}
        </p>
        {explanation && (
          <div className="explanation">
            <strong>Why:</strong> {explanation}
          </div>
        )}
      </div>
    </div>
  )
})

export default function QuizResults({ results, onRestart, onNewQuiz }) {
  const [filter, setFilter] = useState('all')
  const resultsRef = useRef(null)

  const {
    correct,
    wrong,
    skipped,
    total,
    finalPercentage,
    passed,
    timeUsed,
    timeLimit,
    questions,
  } = results

  // ==================== FOCUS MANAGEMENT ====================
  useEffect(() => {
    resultsRef.current?.focus()
    announce(
      `Quiz complete. You scored ${finalPercentage} percent. ${passed ? 'Pass' : 'Fail'}`,
      'assertive'
    )

    // Show mid-content ad in HTML template
    const midAd = document.getElementById('resultsMidAd')
    if (midAd) midAd.hidden = false

    // Populate sidebar related quizzes
    const relatedWidget = document.getElementById('sidebarRelated')
    const relatedList = document.getElementById('relatedList')
    if (relatedWidget && relatedList) {
      relatedWidget.hidden = false
      relatedList.innerHTML = `
        <a href="#" class="related-link">CSS General Science</a>
        <a href="#" class="related-link">PMS Current Affairs</a>
        <a href="#" class="related-link">ISSB Intelligence</a>
      `
    }

    // Populate lifetime stats
    const lifetimeWidget = document.getElementById('sidebarLifetime')
    if (lifetimeWidget) {
      lifetimeWidget.hidden = false
      document.getElementById('ltAttempts').textContent = '12'
      document.getElementById('ltAvg').textContent = '68%'
    }
  }, [finalPercentage, passed])

  // ==================== RESULT MESSAGE ====================
  const getResultMessage = () => {
    if (finalPercentage >= 80) return 'Excellent work! Outstanding performance!'
    if (finalPercentage >= 70) return 'Great job! You performed well.'
    if (finalPercentage >= 60) return 'Good effort! Keep practicing to improve.'
    return 'Keep practicing! You will do better next time.'
  }

  // ==================== STATUS HELPERS ====================
  // BUG FIX #9: Handle -1 index properly
  const getStatus = useCallback((q) => {
    const ans = q.userAnswer
    if (ans === undefined || ans === null || ans === -1) return 'skipped'
    const userKey = q.options?.[ans]?.key
    return userKey === q.correct ? 'correct' : 'wrong'
  }, [])

  // Pre-compute stable review items to pass to memoized children
  const reviewItems = React.useMemo(() => {
    return questions.map((q, i) => {
      const status = getStatus(q)
      const userOpt = status === 'skipped' ? null : q.options?.[q.userAnswer]
      const correctOpt = q.options?.find(o => o.key === q.correct)
      
      return {
        index: i,
        questionText: q.question,
        // BUG FIX #1: userOpt?.text (was 'opt.text' - undefined variable!)
        userText: userOpt ? userOpt.text : 'Not answered',
        correctText: correctOpt ? correctOpt.text : 'N/A',
        explanation: q.explanation,
        status,
      }
    })
  }, [questions, getStatus])

  const filteredItems = reviewItems.filter(item => filter === 'all' || item.status === filter)

  // ==================== FILTER COUNTS ====================
  const getFilterCount = (type) => {
    if (type === 'all') return total
    return reviewItems.filter(item => item.status === type).length
  }

  // ==================== SHARE ====================
  // BUG FIX #15: Sanitize URL - remove query parameters that might contain tokens
  const shareResults = async () => {
    const text = `I scored ${finalPercentage}% on TayariWeb Custom Quiz! Test your knowledge at`
    // Strip query params to avoid leaking tokens/session IDs
    const url = window.location.origin + window.location.pathname

    try {
      if (navigator.share) {
        await navigator.share({
          title: 'My Quiz Results - TayariWeb',
          text,
          url,
        })
      } else if (navigator.clipboard) {
        await navigator.clipboard.writeText(`${text} ${url}`)
        alert('Results copied to clipboard!')
      } else {
        window.prompt('Copy this text:', `${text} ${url}`)
      }
    } catch (err) {
      console.error('Share failed:', err)
    }
  }

  return (
    <div className="results-wrapper">
      <section
        className="results-block"
        id="resultsBlock"
        aria-label="Quiz Results"
        tabIndex={-1}
        ref={resultsRef}
      >
        {/* Results Top */}
        <div className="results-top">
          <h2>Quiz Complete</h2>
          <div className="score-big">{finalPercentage}%</div>
          <div className={`result-tag ${passed ? 'passed' : 'failed'}`}>
            {passed ? 'PASSED' : 'FAILED'}
          </div>
          <p className="result-message">{getResultMessage()}</p>
        </div>

        {/* Stats Line */}
        <div className="stats-line">
          <div className="stat-unit correct">
            <span className="stat-num">{correct}</span>
            <span className="stat-name">Correct</span>
          </div>
          <div className="stat-unit wrong">
            <span className="stat-num">{wrong}</span>
            <span className="stat-name">Wrong</span>
          </div>
          <div className="stat-unit skipped">
            <span className="stat-num">{skipped}</span>
            <span className="stat-name">Skipped</span>
          </div>
          <div className="stat-unit time">
            <span className="stat-num">
              {timeLimit > 0 ? formatTime(timeUsed) : 'N/A'}
            </span>
            <span className="stat-name">Time</span>
          </div>
        </div>

        {/* Performance Breakdown */}
        <div className="performance-breakdown">
          <h3>Performance Analysis</h3>
          <div className="breakdown-grid">
            <div className="breakdown-item">
              <span className="breakdown-value">
                {total > 0 ? Math.round((correct / total) * 100) : 0}%
              </span>
              <span className="breakdown-label">Accuracy</span>
            </div>
            <div className="breakdown-item">
              <span className="breakdown-value">
                {total > 0 ? Math.round(((total - skipped) / total) * 100) : 0}%
              </span>
              <span className="breakdown-label">Completion</span>
            </div>
            <div className="breakdown-item">
              <span className="breakdown-value">{total - skipped}</span>
              <span className="breakdown-label">Attempted</span>
            </div>
            <div className="breakdown-item">
              <span className="breakdown-value">
                {timeLimit > 0 ? formatTime(timeUsed) : 'N/A'}
              </span>
              <span className="breakdown-label">Time Taken</span>
            </div>
          </div>
        </div>

        {/* Study Recommendations */}
        <div className="study-recommendations">
          <h3>Study Recommendations</h3>
          <div className="recommendation-list">
            {wrong > 0 && (
              <div className="rec-item rec-wrong">
                <span className="rec-icon" aria-hidden="true">
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                    <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
                  </svg>
                </span>
                <div className="rec-content">
                  <strong>Review Wrong Answers</strong>
                  <span>You missed {wrong} questions. Focus on these topics in your next study session.</span>
                </div>
              </div>
            )}
            {skipped > 0 && (
              <div className="rec-item rec-skipped">
                <span className="rec-icon" aria-hidden="true">
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                    <circle cx="12" cy="12" r="10"/><polyline points="12 16 12 12 16 12"/>
                  </svg>
                </span>
                <div className="rec-content">
                  <strong>Time Management</strong>
                  <span>You skipped {skipped} questions. Practice pacing to attempt all questions.</span>
                </div>
              </div>
            )}
            {finalPercentage < 60 && (
              <div className="rec-item rec-focus">
                <span className="rec-icon" aria-hidden="true">
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                    <path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/>
                  </svg>
                </span>
                <div className="rec-content">
                  <strong>Focus Areas</strong>
                  <span>Your score is below passing. Review fundamentals before attempting again.</span>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Weak Areas Breakdown */}
        {wrong > 0 && (
          <div className="weak-areas">
            <h3>Areas to Improve</h3>
            <div className="weak-list">
              {reviewItems
                .filter(item => item.status === 'wrong')
                .slice(0, 5)
                .map((item, i) => (
                  <div key={i} className="weak-item">
                    <span className="weak-num">{i + 1}</span>
                    <span className="weak-text">{item.questionText.substring(0, 80)}...</span>
                  </div>
                ))}
            </div>
          </div>
        )}

        {/* Review Section */}
        <div className="review-wrap">
          <h3>Review Answers</h3>
          <div className="review-filters" role="group" aria-label="Filter results">
            {FILTER_TYPES.map(type => (
              <button
                key={type}
                className={`filter-tag ${filter === type ? 'active' : ''}`}
                onClick={() => {
                  setFilter(type)
                  announce(`Showing ${type} questions. ${getFilterCount(type)} items.`, 'polite')
                }}
              >
                {type === 'all' ? 'All' :
                 type === 'correct' ? 'Correct' :
                 type === 'wrong' ? 'Wrong' : 'Skipped'}
                <span className="filter-count">{getFilterCount(type)}</span>
              </button>
            ))}
          </div>
          <div className="review-list">
            {filteredItems.map(item => (
              <ReviewItem
                key={item.index}
                index={item.index}
                questionText={item.questionText}
                userText={item.userText}
                correctText={item.correctText}
                explanation={item.explanation}
                status={item.status}
              />
            ))}
          </div>
        </div>

        {/* Feedback */}
        <div className="fb">
          <h4>Was this helpful?</h4>
          <div className="fbb">
            <button className="fb-btn fb-like" onClick={() => window.fd && window.fd('like')}>
              <span className="fb-icon" aria-hidden="true">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3zM7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"/>
                </svg>
              </span>
              Helpful
            </button>
            <button className="fb-btn fb-dislike" onClick={() => window.fd && window.fd('dislike')}>
              <span className="fb-icon" aria-hidden="true">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M10 15v4a3 3 0 0 0 3 3l4-9V2H5.72a2 2 0 0 0-2 1.7l-1.38 9a2 2 0 0 0 2 2.3zM17 2h3a2 2 0 0 1 2 2v7a2 2 0 0 1-2 2h-3"/>
                </svg>
              </span>
              Not Helpful
            </button>
          </div>
        </div>

        {/* Action Line */}
        <div className="action-line">
          <button className="action-btn outline" onClick={onRestart}>
            <span className="btn-icon" aria-hidden="true">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/>
              </svg>
            </span>
            Retake Same Quiz
          </button>
          <button className="action-btn solid" onClick={onNewQuiz}>
            <span className="btn-icon" aria-hidden="true">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <line x1="5" y1="12" x2="19" y2="12"/><line x1="12" y1="5" x2="12" y2="19"/>
              </svg>
            </span>
            New Quiz
          </button>
          <button className="action-btn outline" onClick={shareResults}>
            <span className="btn-icon" aria-hidden="true">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/>
                <line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/>
              </svg>
            </span>
            Share Results
          </button>
        </div>
      </section>
    </div>
  )
}