import React, { useState, useCallback, useEffect } from 'react'
import QuizConfig from './QuizConfig'
import QuizRunner from './QuizRunner'
import QuizResults from './QuizResults'
import { loadFromSession, clearSession, announce } from '../shared/api'

const PHASES = {
  CONFIG: 'config',
  RUNNING: 'running',
  RESULTS: 'results',
}

const STORAGE_KEYS = {
  CONFIG: 'tayari_quiz_config',
  ACTIVE: 'tayari_quiz_active',
  PHASE: 'tayari_quiz_phase',
}

export default function CustomQuizApp() {
  const [phase, setPhase] = useState(PHASES.CONFIG)
  const [quizData, setQuizData] = useState(null)
  const [quizConfig, setQuizConfig] = useState(null)
  const [results, setResults] = useState(null)

  useEffect(() => {
    try {
      const savedPhase = sessionStorage.getItem(STORAGE_KEYS.PHASE)
      const saved = loadFromSession(STORAGE_KEYS.ACTIVE, 60 * 60 * 1000)
      
      if (saved && saved.questions?.length > 0 && savedPhase === PHASES.RUNNING) {
        const confirmed = window.confirm(
          'You have an unfinished quiz. Would you like to resume where you left off?'
        )
        if (confirmed) {
          setQuizData(saved)
          setQuizConfig(saved.config)
          setPhase(PHASES.RUNNING)
          announce('Resuming previous quiz session', 'polite')
        } else {
          clearSession(STORAGE_KEYS.ACTIVE)
          clearSession(STORAGE_KEYS.CONFIG)
          sessionStorage.removeItem(STORAGE_KEYS.PHASE)
        }
      }
    } catch (err) {
      console.error('Session restore failed:', err)
      clearSession(STORAGE_KEYS.ACTIVE)
      clearSession(STORAGE_KEYS.CONFIG)
      sessionStorage.removeItem(STORAGE_KEYS.PHASE)
    }
  }, [])

  const handleQuizGenerated = useCallback((data, config) => {
    setQuizData(data)
    setQuizConfig(config)
    setPhase(PHASES.RUNNING)
    sessionStorage.setItem(STORAGE_KEYS.PHASE, PHASES.RUNNING)
    announce(`Quiz started. Question 1 of ${data.questions.length}`, 'assertive')
  }, [])

  const handleQuizComplete = useCallback((quizResults) => {
    setResults(quizResults)
    setPhase(PHASES.RESULTS)
    sessionStorage.setItem(STORAGE_KEYS.PHASE, PHASES.RESULTS)
    clearSession(STORAGE_KEYS.ACTIVE)
    clearSession(STORAGE_KEYS.CONFIG)
    announce(
      `Quiz complete. You scored ${quizResults.finalPercentage} percent. ${quizResults.passed ? 'Pass' : 'Fail'}`,
      'assertive'
    )
  }, [])

  const handleRestart = useCallback(() => {
    clearSession(STORAGE_KEYS.ACTIVE)
    clearSession(STORAGE_KEYS.CONFIG)
    sessionStorage.removeItem(STORAGE_KEYS.PHASE)
    // Reset all state instead of reloading page
    setPhase(PHASES.CONFIG)
    setQuizData(null)
    setQuizConfig(null)
    setResults(null)
    announce('Quiz reset. Configure a new quiz.', 'polite')
  }, [])

  const handleNewQuiz = useCallback(() => {
    clearSession(STORAGE_KEYS.ACTIVE)
    clearSession(STORAGE_KEYS.CONFIG)
    sessionStorage.removeItem(STORAGE_KEYS.PHASE)
    setPhase(PHASES.CONFIG)
    setQuizData(null)
    setQuizConfig(null)
    setResults(null)
    announce('Starting new quiz configuration', 'polite')
  }, [])

  return (
    <>
      {phase === PHASES.CONFIG && (
        <QuizConfig onQuizGenerated={handleQuizGenerated} />
      )}
      {phase === PHASES.RUNNING && quizData && (
        <QuizRunner
          questions={quizData.questions}
          config={quizConfig}
          onComplete={handleQuizComplete}
          savedState={quizData}
        />
      )}
      {phase === PHASES.RESULTS && results && (
        <QuizResults
          results={results}
          onRestart={handleRestart}
          onNewQuiz={handleNewQuiz}
        />
      )}
    </>
  )
}