import { memo } from 'react';

const JumpBar = memo(function JumpBar({ total, current, answers, bookmarks, onJump, questionIds }) {
  return (
    <div className="jump-bar">
      <span className="jump-label">Go to:</span>
      <div className="jump-numbers">
        {Array.from({ length: total }, (_, i) => {
          const qid = questionIds ? questionIds[i] : i;
          const classes = ['jump-num'];
          if (i === current) classes.push('current');
          if (answers[qid] !== undefined) classes.push('answered');
          if (bookmarks.has(qid)) classes.push('bookmarked');

          return (
            <button
              key={i}
              type="button"
              className={classes.join(' ')}
              onClick={() => onJump(i)}
              aria-label={`Jump to question ${i + 1}${bookmarks.has(qid) ? ' (bookmarked)' : ''}${answers[qid] !== undefined ? ' (answered)' : ''}`}
              aria-current={i === current ? 'true' : undefined}
            >
              {i + 1}
            </button>
          );
        })}
      </div>
    </div>
  );
});

export default JumpBar;